-- Generated by scripts/season-pass-sql.mjs: never edit by hand. The Season Pass (Autumn 2026 on), plan-farmpas/plan.md §8 and §11.
-- Run once, in the SQL editor, after a backup of the functions it patches (pg_get_functiondef of each in LIVE_MD5 below). Everything
-- runs in one transaction; a check that fails rolls all of it back.
begin;
set local lock_timeout='5s';

-- 1. Purchases: pack 'season', €19.99, no diamonds, coins or VIP, and the season it is for. One per farmer per season.
alter table public.harvest_purchases drop constraint if exists harvest_purchases_pack_check;
alter table public.harvest_purchases add constraint harvest_purchases_pack_check check (pack = any (array['50','100','150','300','500','600','1000','1250','2000','3500','starter','offer','pass','season']));
alter table public.harvest_purchases drop constraint if exists harvest_purchases_amount_cents_check;
alter table public.harvest_purchases add constraint harvest_purchases_amount_cents_check check (amount_cents = any (array[199,299,499,999,1999,2499]));
alter table public.harvest_purchases drop constraint if exists harvest_purchases_diamonds_check;
alter table public.harvest_purchases add constraint harvest_purchases_diamonds_check check (
 (pack='offer' and diamonds between 0 and 20000) or (pack in ('pass','season') and diamonds=0) or diamonds = any (array[50,100,150,300,500,600,1000,1250,2000,3500]));
alter table public.harvest_purchases drop constraint if exists harvest_pack_amount_matches;
alter table public.harvest_purchases add constraint harvest_pack_amount_matches check (
 (pack = any (array['50','100','150']) and diamonds=(case when pack ~ '^[0-9]+$' then pack::integer else 0 end) and coins=0 and amount_cents=199) or
 (pack='500' and diamonds=500 and coins=0 and amount_cents=499) or
 (pack = any (array['300','600','1250']) and diamonds=(case when pack ~ '^[0-9]+$' then pack::integer else 0 end) and coins=0 and amount_cents=999) or
 (pack = any (array['1000','2000','3500']) and diamonds=(case when pack ~ '^[0-9]+$' then pack::integer else 0 end) and coins=0 and amount_cents=2499) or
 (pack='starter' and diamonds = any (array[300,500]) and coins=10000 and amount_cents=299) or
 (pack='offer' and offer_id is not null and amount_cents=499 and coins between 0 and 10000000 and vip_days in (0,7,30,60,90) and (diamonds>0 or coins>0 or vip_days>0)) or
 (pack='pass' and pass_id is not null and diamonds=0 and coins=0 and vip_days=0 and amount_cents=499) or
 (pack='season' and pass_id is not null and diamonds=0 and coins=0 and vip_days=0 and amount_cents=1999));
create unique index if not exists harvest_one_season_per_player on public.harvest_purchases(player_id, pass_id)
 where pack='season' and status<>'expired';

-- The seasons the game knows (game/farm-state.js SEASONS; a test keeps this file equal to it). They follow each other, so the season
-- running now is the first one that has not ended.
create or replace function public.harvest_seasons() returns table(id text, ends_at timestamptz, claim_until timestamptz)
 language sql immutable set search_path to '' as $f$
 select * from (values
  ('autumn-2026',timestamptz '2026-12-22T00:00:00.000Z',timestamptz '2026-12-29T00:00:00.000Z')) s(id,ends_at,claim_until)
$f$;
-- The season a paid season purchase opens: its own until the end of its collecting week; after that the season running now, when the
-- farm does not have it yet; else null (nothing to give: the admins refund it).
create or replace function public.harvest_season_target(p_pass text, p_state jsonb) returns text language sql stable set search_path to '' as $f$
 select case when exists(select 1 from public.harvest_seasons() s where s.id=p_pass and now()<s.claim_until) then p_pass
  else (select x.id from (select s.id from public.harvest_seasons() s where s.id<>p_pass and now()<s.ends_at order by s.ends_at limit 1) x
   where not (case when jsonb_typeof(p_state->'passPremium')='array' then p_state->'passPremium' else '[]'::jsonb end) ? x.id) end
$f$;
-- Paid for a season that has ended, with nothing to give: a notice to every admin to refund it (as a payment after an account was deleted).
create or replace function public.harvest_season_late_notice(p_purchase uuid) returns void language plpgsql security definer set search_path to '' as $f$
declare p public.harvest_purchases%rowtype; who text; admin_id uuid;
begin
 select * into p from public.harvest_purchases where id=p_purchase;
 select coalesce(s.username,'A farmer') into who from public.player_stats s where s.player_id=p.player_id;
 for admin_id in select u.id from auth.users u where public.chat_staff_role(u.id)='admin' loop
  insert into public.player_notices(player_id,kind,body) values(admin_id,'purchase',coalesce(who,'A farmer')||' paid for the Season Pass ('||coalesce(p.pass_id,'?')
   ||') after it ended, and already has the season running now. Nothing was given: refund it ('||coalesce(p.store,'?')||', purchase '||p.id||').');
 end loop;
exception when others then null;   -- a notice never stands in the way of the payment
end $f$;
-- The paid looks of a season (its paid row, the avatar of the purchase too): what a refund takes off the farmer's card.
create or replace function public.harvest_season_paid_looks(p_pass text) returns text[] language sql immutable set search_path to '' as $f$
 select case p_pass when 'autumn-2026' then array['season-autumn-2026-harvest-chef','autumn-2026-color-pumpkin','autumn-2026-title-pumpkin-whisperer','autumn-2026-frame','autumn-2026-emblem','autumn-2026-bg-orchard','autumn-2026-color-apple-red','autumn-2026-golden-rod','autumn-2026-tractor','autumn-2026-title-autumn-legend','season-autumn-2026-pumpkin-royal','autumn-2026-golden-pumpkin']::text[] else array[]::text[] end
$f$;

-- 2. Patches in place, each on the body read live on 20 Oct 2026.
create or replace function pg_temp.season_patch(p_fn text, p_md5 text, p_from text[], p_to text[]) returns void language plpgsql as $f$
declare fn regprocedure:=('public.'||p_fn)::regprocedure; src text; def text; at integer; i integer;
begin
 select prosrc into src from pg_proc where oid=fn;
 if md5(src)<>p_md5 then raise exception '% is not the body read on 20 Oct 2026 (md5 % instead of %): read it again and regenerate',p_fn,md5(src),p_md5; end if;
 for i in 1..coalesce(array_length(p_from,1),0) loop
  if (length(src)-length(replace(src,p_from[i],'')))/length(p_from[i])<>1 then raise exception '%: part % is not there exactly once',p_fn,i; end if;
  src:=replace(src,p_from[i],p_to[i]);
 end loop;
 if position('$function$' in src)>0 then raise exception '%: unexpected quote',p_fn; end if;
 def:=pg_get_functiondef(fn);at:=position('AS $function$' in def);
 if at=0 then raise exception '%: no body to replace',p_fn; end if;
 execute substring(def from 1 for at+2)||'$function$'||src||'$function$';
end $f$;
select pg_temp.season_patch('harvest_purchase_grant(uuid)','bdb7d88b6d208305f39ba78c3ed4a630',array['declare purchase public.harvest_purchases%rowtype; farm_state jsonb; goods jsonb; crop text; vip_until bigint;','if purchase.pack=''pass'' then
  farm_state:=jsonb_set(farm_state,''{passPremium}'',']::text[],array['declare purchase public.harvest_purchases%rowtype; farm_state jsonb; goods jsonb; crop text; vip_until bigint; target text;','-- The Season Pass (season-pass-engine.sql): the season it is for, or the one running now when paid after that one''s collecting
 -- week (harvest_season_target); none: nothing is given and the admins are asked to refund it.
 if purchase.pack=''season'' then
  target:=public.harvest_season_target(purchase.pass_id,farm_state);
  if target is null then perform public.harvest_season_late_notice(purchase.id);
  else
   if target<>purchase.pass_id then
    begin update public.harvest_purchases set pass_id=target where id=purchase.id; exception when unique_violation then null; end;
   end if;
   farm_state:=jsonb_set(farm_state,''{passPremium}'',(select coalesce(jsonb_agg(distinct v),''[]''::jsonb) from jsonb_array_elements(
    (case when jsonb_typeof(farm_state->''passPremium'')=''array'' then farm_state->''passPremium'' else ''[]''::jsonb end)||jsonb_build_array(target)) v));
  end if;
 end if;
 if purchase.pack=''pass'' then
  farm_state:=jsonb_set(farm_state,''{passPremium}'',']::text[]);
select pg_temp.season_patch('harvest_purchase_alert()','a1f6b8662c16262fff9f8da70456809c',array['when new.pack=''pass'' then ''the Halloween Pass''']::text[],array['when new.pack=''pass'' then ''the Halloween Pass''
  when new.pack=''season'' then ''the Season Pass (''||coalesce(new.pass_id,''?'')||'')''']::text[]);
select pg_temp.season_patch('harvest_purchase_log()','ba721cf81a694a85b3319a0a6614bfc4',array['when new.pack=''pass'' then ''the Halloween Pass''']::text[],array['when new.pack=''pass'' then ''the Halloween Pass''
    when new.pack=''season'' then ''the Season Pass (''||coalesce(new.pass_id,''?'')||'')''']::text[]);
select pg_temp.season_patch('harvest_revoke_play_purchases(jsonb)','3b4819bb52aedbf169f7cbec9766333b',array['when purchase.pack=''pass'' then ''the Halloween Pass''']::text[],array['when purchase.pack=''pass'' then ''the Halloween Pass'' when purchase.pack=''season'' then ''the Season Pass''']::text[]);
select pg_temp.season_patch('harvest_revoke_apple_purchases(jsonb)','bc37428b02d4211adb589cff0a6c91e8',array['when purchase.pack=''pass'' then ''the Halloween Pass''']::text[],array['when purchase.pack=''pass'' then ''the Halloween Pass'' when purchase.pack=''season'' then ''the Season Pass''']::text[]);
select pg_temp.season_patch('harvest_revoke_kong_purchases(jsonb)','73bf75584212324657f21e7192502f65',array['when purchase.pack=''pass'' then ''the Halloween Pass''']::text[],array['when purchase.pack=''pass'' then ''the Halloween Pass'' when purchase.pack=''season'' then ''the Season Pass''']::text[]);
select pg_temp.season_patch('harvest_event_claim(uuid,uuid)','de2cdc930a667bc9c80f3737fca9929c',array['farm.state:=jsonb_set(jsonb_set(farm.state,''{coins}'',']::text[],array['-- Counted in the farm for the Season Pass (stats.events_claimed, season-pass-engine.sql).
 farm.state:=jsonb_set(farm.state,''{stats,events_claimed}'',to_jsonb(coalesce((farm.state#>>''{stats,events_claimed}'')::integer,0)+1));
 farm.state:=jsonb_set(jsonb_set(farm.state,''{coins}'',']::text[]);

-- 3. A refund of a season purchase: the season leaves passPremium, the farmer's worn paid looks and a paid season avatar go back to the
-- default; the game takes back the paid diamonds and paid looks at the next load (game/farm-state.js seasonRefund).
create or replace function public.harvest_season_refund() returns trigger language plpgsql security definer set search_path to '' as $f$
declare farm_state jsonb; paid text[]:=public.harvest_season_paid_looks(new.pass_id);
begin
 if new.player_id is null or new.pass_id is null then return new; end if;
 select state into farm_state from public.player_farms where player_id=new.player_id for update;
 if found and jsonb_typeof(farm_state->'passPremium')='array' and farm_state->'passPremium' ? new.pass_id then
  farm_state:=jsonb_set(farm_state,'{passPremium}',(select coalesce(jsonb_agg(v),'[]'::jsonb) from jsonb_array_elements(farm_state->'passPremium') v where v<>to_jsonb(new.pass_id)));
  update public.player_farms set state=farm_state,revision=revision+1,updated_at=now() where player_id=new.player_id;
 end if;
 update public.player_stats set look=(select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb) from jsonb_each(coalesce(look,'{}'::jsonb)) e where not (e.value #>> '{}') = any(paid)),
  avatar_id=case when avatar_id = any(paid) then 'default' else avatar_id end where player_id=new.player_id;
 insert into public.player_logs(player_id,category,action,text) values(new.player_id,'purchase','refund',
  'Season Pass ('||new.pass_id||') refunded: its paid rewards are taken back as far as the farm still has them');
 return new;
end $f$;
drop trigger if exists harvest_season_refund on public.harvest_purchases;
create trigger harvest_season_refund after update of status on public.harvest_purchases for each row
 when (new.pack='season' and new.status='refunded' and old.status='credited') execute function public.harvest_season_refund();
-- New functions get EXECUTE for anon and authenticated by this database's default privileges: only the database itself and farm-api's
-- service role may call these (harvest_season_late_notice writes admin notices).
revoke all on function public.harvest_seasons(), public.harvest_season_target(text,jsonb), public.harvest_season_late_notice(uuid),
 public.harvest_season_paid_looks(text), public.harvest_season_refund() from public, anon, authenticated;
grant execute on function public.harvest_seasons(), public.harvest_season_target(text,jsonb), public.harvest_season_late_notice(uuid),
 public.harvest_season_paid_looks(text) to service_role;

-- 4. What a farmer wears on their card. Only farm-api writes it (the service role); everyone signed in may read it.
alter table public.player_stats add column if not exists look jsonb not null default '{}'::jsonb;
alter table public.player_stats drop constraint if exists player_stats_look_check;
alter table public.player_stats add constraint player_stats_look_check check (jsonb_typeof(look)='object' and pg_column_size(look)<1000);
grant select (look) on public.player_stats to authenticated;

-- 5. Season avatars: the existing list, or a season id ('season-autumn-2026-harvest-chef'), so no new SQL per season.
do $d$
declare def text;
begin
 select pg_get_constraintdef(oid) into def from pg_constraint where conrelid='public.player_stats'::regclass and conname='player_stats_avatar_id_check';
 if def is null then raise exception 'player_stats_avatar_id_check is missing'; end if;
 if position('season-' in def)=0 then
  execute 'alter table public.player_stats drop constraint player_stats_avatar_id_check';
  execute 'alter table public.player_stats add constraint player_stats_avatar_id_check check ('||substring(def from 7)||' or avatar_id ~ ''^season-[a-z0-9-]{3,60}$'')';
 end if;
end $d$;

-- After-check: everything came out as generated, else nothing of this file stays.
do $d$
declare body text;
begin
 select prosrc into body from pg_proc where oid='public.harvest_purchase_grant(uuid)'::regprocedure;
 if position('harvest_season_target' in body)=0 then raise exception 'grant not patched'; end if;
 select prosrc into body from pg_proc where oid='public.harvest_event_claim(uuid,uuid)'::regprocedure;
 if position('events_claimed' in body)=0 then raise exception 'event claim not patched'; end if;
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in
  ('harvest_purchase_alert','harvest_purchase_log','harvest_revoke_play_purchases','harvest_revoke_apple_purchases','harvest_revoke_kong_purchases')
  and position('the Season Pass' in p.prosrc)>0)<>5 then raise exception 'texts not patched'; end if;
 if public.harvest_season_target('autumn-2026','{}'::jsonb) is distinct from (case when now()<timestamptz '2026-12-29T00:00:00.000Z' then 'autumn-2026' end)
  then raise exception 'season target'; end if;
 if not exists(select 1 from pg_trigger where tgname='harvest_season_refund') then raise exception 'refund trigger'; end if;
 if not exists(select 1 from information_schema.columns where table_schema='public' and table_name='player_stats' and column_name='look') then raise exception 'look column'; end if;
 if position('season-' in (select pg_get_constraintdef(oid) from pg_constraint where conname='player_stats_avatar_id_check'))=0 then raise exception 'avatar check'; end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'harvest_season%'
  and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute'))) then raise exception 'season functions open to players'; end if;
end $d$;

commit;
